// JSON is the source of truth. Bundle all locales for immediate, offline-ready UI.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const locales = {};
for (const locale of ['en', 'fr-TD', 'ar-TD']) {
    locales[locale] = JSON.parse(fs.readFileSync(path.join(root, 'assets/locales', locale + '.json'), 'utf8'));
}
fs.writeFileSync(path.join(root, 'assets/locales/catalog.js'),
    '// Generated by node scripts/build-locales.cjs; edit the JSON locale files.\nwindow.FAMINA_TRANSLATIONS = ' +
    JSON.stringify(locales).replace(/</g, '\\u003c') + ';\n');
